import AppKit

/// The Clip tab's **Motion** section (spec §4.3, road map 5's E2) — what a
/// clip does on its way in, on its way out, and all the way through.
///
/// An `extension VideoPane` in a file of its own, `VideoPane+Transition.swift`'s
/// shape, because `VideoPane.swift` is over the size cap and may not grow.
///
/// **Every write is PER CLIP.** A `motion` patch replaces the whole object
/// (`MotionProps.dictionary` always writes three keys), so one `set_video`
/// over several ids would stamp the first clip's other two slots onto every
/// other clip. Each row therefore reads THAT clip's base motion, changes the
/// one slot or field, and emits that clip's own op — through
/// `ops(video:for:)`, whose `structural` puts motion on the base props even
/// inside an action. Reset alone is selection-wide, since every clip gets the
/// same value. Reads are the first clip's, the section rule.
extension VideoPane {
    // MARK: Motion

    func motionSection() -> InspectorSection {
        let binding = self.binding
        let edges = EdgeMotion.allCases
        let durings = DuringMotion.allCases
        func motion() -> MotionProps { binding.videoProps.motion ?? MotionProps() }
        /// One op per clip over the selection's pixel clips; `step` answers
        /// the clip's next motion, or nil to skip the clip.
        func perClip(_ step: (ClipSnapshot, MotionProps) -> MotionProps?) -> [ReelOp] {
            var ops: [ReelOp] = []
            for clip in binding.videoClips {
                let current = clip.videoProps.motion ?? MotionProps()
                guard let next = step(clip, current) else { continue }
                ops.append(
                    contentsOf: binding.ops(video: VideoPatch(motion: .some(next)), for: clip))
            }
            return ops
        }
        func edgeKind(_ index: Int) -> EdgeMotion? {
            index == 0 ? nil : edges[min(max(index - 1, 0), edges.count - 1)]
        }
        /// A chosen kind keeps the slot's stored duration, else the core's
        /// own 0.5 s default (`MotionEdge()`).
        func edge(_ kind: EdgeMotion?, keeping stored: MotionEdge?) -> MotionEdge? {
            guard let kind = kind else { return nil }
            return MotionEdge(kind: kind, duration: stored?.duration ?? MotionEdge().duration)
        }
        func summary() -> String {
            let m = motion()
            var parts: [String] = []
            if let e = m.inEdge { parts.append("in " + e.displayName.lowercased()) }
            if let e = m.out { parts.append("out " + e.displayName.lowercased()) }
            if let d = m.during { parts.append(d.kind.displayName.lowercased()) }
            return parts.isEmpty ? "off" : parts.joined(separator: " · ")
        }
        func inactiveNote() -> String? {
            let selected = binding.videoClips.map { $0.videoProps.motion }
            let inactiveIn = selected.contains { $0?.inEdge.map { !$0.isActive } ?? false }
            let inactiveOut = selected.contains { $0?.out.map { !$0.isActive } ?? false }
            guard inactiveIn || inactiveOut else { return nil }
            let slots = [inactiveIn ? "In" : nil, inactiveOut ? "Out" : nil]
                .compactMap { $0 }.joined(separator: " and ")
            return "Selection includes inactive \(slots) motion (zero duration). "
                + "Increase Duration to reactivate; choose None to clear."
        }

        let preview = commandButton(
            "Preview", #selector(EditorViewController.previewClipMotion(_:)),
            toolTip:
                "Play the clip in a loop: sets the in/out range to the clip and turns Loop on"
                + " — both stay until you clear them")

        return InspectorSection(
            id: "video.motion", title: "Motion presets",
            summary: summary,
            reset: { binding.apply("Motion", video: VideoPatch(motion: .some(nil))) },
            defaultExpanded: false,
            rows: [
                InspectorNoteLabel(wraps: true, note: inactiveNote),
                inspectorPopupRow(
                    "In", binding, name: "Motion In", items: ["None"] + edges.map(\.displayName),
                    read: { motion().inEdge.map { (edges.firstIndex(of: $0.kind) ?? 0) + 1 } ?? 0 },
                    ops: { index in
                        perClip { _, m in
                            m.with { $0.inEdge = edge(edgeKind(index), keeping: m.inEdge) }
                        }
                    },
                    mixed: { binding.mixedVideo { $0.motion?.inEdge?.kind } }),
                // 0.1 s to 10 s: a few frames at the short end, and far longer
                // than any entrance is meant to take at the long one.
                inspectorValueRow(
                    "In Duration", binding, name: "Motion In Duration", unit: " s", decimals: 2,
                    min: 0.1, max: 10, quick: [0.25, 0.5, 1], slider: false,
                    read: { ReelTime.seconds(motion().inEdge?.duration ?? MotionEdge().duration) },
                    ops: { value in
                        perClip { _, m in
                            guard m.inEdge != nil else { return nil }
                            return m.with {
                                $0.inEdge?.duration = binding.frameTicks(seconds: value)
                            }
                        }
                    },
                    mixed: { binding.mixedVideo { $0.motion?.inEdge?.duration } },
                    enabled: { motion().inEdge != nil }),
                inspectorPopupRow(
                    "Out", binding, name: "Motion Out", items: ["None"] + edges.map(\.displayName),
                    read: { motion().out.map { (edges.firstIndex(of: $0.kind) ?? 0) + 1 } ?? 0 },
                    ops: { index in
                        perClip { _, m in
                            m.with { $0.out = edge(edgeKind(index), keeping: m.out) }
                        }
                    },
                    mixed: { binding.mixedVideo { $0.motion?.out?.kind } }),
                // The same range as In Duration, for the same reason.
                inspectorValueRow(
                    "Out Duration", binding, name: "Motion Out Duration", unit: " s", decimals: 2,
                    min: 0.1, max: 10, quick: [0.25, 0.5, 1], slider: false,
                    read: { ReelTime.seconds(motion().out?.duration ?? MotionEdge().duration) },
                    ops: { value in
                        perClip { _, m in
                            guard m.out != nil else { return nil }
                            return m.with { $0.out?.duration = binding.frameTicks(seconds: value) }
                        }
                    },
                    mixed: { binding.mixedVideo { $0.motion?.out?.duration } },
                    enabled: { motion().out != nil }),
                inspectorPopupRow(
                    "During", binding, name: "Motion During",
                    items: ["None"] + durings.map(\.displayName),
                    read: {
                        motion().during.map { (durings.firstIndex(of: $0.kind) ?? 0) + 1 } ?? 0
                    },
                    ops: { index in
                        perClip { _, m in
                            guard index > 0 else { return m.with { $0.during = nil } }
                            // A kind keeps the stored amount and period, else
                            // the core's own defaults (`MotionDuring()`).
                            var during = m.during ?? MotionDuring()
                            during.kind = durings[min(index - 1, durings.count - 1)]
                            return m.with { $0.during = during }
                        }
                    },
                    mixed: { binding.mixedVideo { $0.motion?.during?.kind } }),
                // Written as a percentage because the model's 0–1 reads as a
                // strength; `/ 100` at the write is the only conversion.
                inspectorValueRow(
                    "Amount", binding, name: "Motion Amount", unit: "%", decimals: 0,
                    min: 0, max: 100, quick: [25, 50, 75, 100], slider: false,
                    read: { (motion().during?.amount ?? MotionDuring().amount) * 100 },
                    ops: { value in
                        perClip { _, m in
                            guard m.during != nil else { return nil }
                            return m.with { $0.during?.amount = value / 100 }
                        }
                    },
                    mixed: { binding.mixedVideo { $0.motion?.during?.amount } },
                    enabled: { motion().during != nil }),
                // 0.1 s to 10 s: a cycle shorter than a few frames aliases, and
                // one longer than ten seconds no longer reads as a cycle.
                // Disabled for drift, which ignores the period.
                inspectorValueRow(
                    "Period", binding, name: "Motion Period", unit: " s", decimals: 2,
                    min: 0.1, max: 10, quick: [0.25, 0.5, 1, 2], slider: false,
                    read: {
                        ReelTime.seconds(motion().during?.period ?? MotionDuring().period)
                    },
                    ops: { value in
                        perClip { _, m in
                            guard m.during != nil else { return nil }
                            return m.with { $0.during?.period = binding.frameTicks(seconds: value) }
                        }
                    },
                    mixed: { binding.mixedVideo { $0.motion?.during?.period } },
                    enabled: {
                        guard let d = motion().during else { return false }
                        return d.kind != .drift
                    }),
                inspectorButtonRow([preview]),
            ])
    }
}
        for (index, kind) in TransitionKind.allCases.enumerated() {
            menu.addItem(
                tagged(kind.displayName, #selector(EditorViewController.setTransitionKind(_:)), index))
        }
        menu.addItem(.separator())
        menu.addItem(
            tagged("None", #selector(EditorViewController.setTransitionKind(_:)), -1))
        return menu
    }

    /// Clip ▸ Motion: one submenu per slot, then Preview.
    func motionMenu() -> NSMenu {
        let menu = NSMenu(title: "Motion")
        let edges = EdgeMotion.allCases.map(\.displayName)
        menu.addItem(
            submenuItem(
                motionSlotMenu("In", edges, #selector(EditorViewController.setMotionIn(_:)))))
        menu.addItem(
            submenuItem(
                motionSlotMenu("Out", edges, #selector(EditorViewController.setMotionOut(_:)))))
        menu.addItem(
            submenuItem(
                motionSlotMenu(
                    "During", DuringMotion.allCases.map(\.displayName),
                    #selector(EditorViewController.setMotionDuring(_:)))))
        menu.addItem(.separator())
        menu.addItem(item("Preview", #selector(EditorViewController.previewClipMotion(_:))))
        return menu
    }

    /// Clip ▸ Look (spec §11 GR-7 [b]): the eight looks from `LookKind.allCases`
    /// with the index as the tag, a separator, None as −1 — the
    /// `transitionMenu()` idiom; `validateLookAction` checks and dashes them.
    /// `LookMenuFiller` puts the project's LUTs before None when it opens.
    func lookMenu() -> NSMenu {
        let menu = NSMenu(title: "Look")
        menu.delegate = LookMenuFiller.shared
        for (index, kind) in LookKind.builtIns.enumerated() {
            menu.addItem(tagged(kind.displayName, #selector(EditorViewController.setLook(_:)), index))
        }
        menu.addItem(.separator())
        menu.addItem(SwitchAngleMenuFiller.placeholder())
        return menu
    }

    /// One slot's kinds, the `transitionMenu()` idiom: the index as the tag,
    /// a separator, None as −1.
    private func motionSlotMenu(_ title: String, _ names: [String], _ action: Selector) -> NSMenu {
        let menu = NSMenu(title: title)
        for (index, name) in names.enumerated() {
            menu.addItem(tagged(name, action, index))
        }
        menu.addItem(.separator())
        menu.addItem(tagged("None", action, -1))
        return menu
    }

    /// Built from `ClipLabel.allCases` with the case's index as the tag — the
    /// `transitionMenu()` idiom — so the six colours, their order and their
    /// inks come from the one file that owns them. Each item carries a dot in
    /// its colour: a label IS a colour, and a menu of six colour words that
    /// showed none would make the user picture them.
    func labelMenu() -> NSMenu {
        let menu = NSMenu(title: "Label")
        for (index, label) in ClipLabel.allCases.enumerated() {
            let entry = tagged(
                label.displayName, #selector(EditorViewController.setClipLabel(_:)), index)
            entry.image = Self.labelDot(label.color)
            menu.addItem(entry)
        }
        menu.addItem(.separator())
        menu.addItem(tagged("None", #selector(EditorViewController.setClipLabel(_:)), -1))
        return menu
    }

    /// A 10 pt filled circle — the timeline strip's 6 pt label dot at menu
    /// size. Not a template image: the point of it is its colour.
    private static func labelDot(_ color: NSColor) -> NSImage {
        let image = NSImage(size: NSSize(width: 10, height: 10), flipped: false) { rect in
            color.setFill()
            NSBezierPath(ovalIn: rect.insetBy(dx: 0.5, dy: 0.5)).fill()
            return true
        }
        return image
    }
}

/// Clip ▸ Look ▸'s LUT rows (spec §11 GR-8 [b]): between the eight's separator
/// and None, the project's `.cube` LUTs in media-list order, tag −2 with the
/// media id as `representedObject`, then a second separator — none of either
/// with no LUT. Rewritten each time the menu opens (`menuNeedsUpdate`), for
/// the main window's project; `UIMenu.fillDynamic` asks it for a named window.
final class LookMenuFiller: NSObject, NSMenuDelegate {
    static let shared = LookMenuFiller()

    func menuNeedsUpdate(_ menu: NSMenu) {
        fill(menu, for: NSApp.mainWindow)
    }

    func fill(_ menu: NSMenu, for window: NSWindow?) {
        let document = window?.windowController?.document as? ProjectDocument
        Self.fill(menu, luts: document.map { LookGallery.luts(in: $0.project.snapshot) } ?? [])
    }

    static func fill(_ menu: NSMenu, luts: [MediaSnapshot]) {
        guard let first = menu.items.firstIndex(where: \.isSeparatorItem) else { return }
        while menu.items.count > first + 2 { menu.removeItem(at: first + 1) }

    /// The sender's tag indexes `EdgeMotion.allCases`; −1 is None.
    @objc func setMotionOut(_ sender: Any?) { setMotionCommand(slot: .out, sender: sender) }

    /// The sender's tag indexes `DuringMotion.allCases`; −1 is None.
    @objc func setMotionDuring(_ sender: Any?) { setMotionCommand(slot: .during, sender: sender) }

    /// Preview: the in/out range set to the first target and Loop turned on,
    /// then play from its start. Both stay until the person clears them —
    /// the Preview button's tooltip says so.
    @objc func previewClipMotion(_ sender: Any?) {
        guard let document = document, let clip = motionTargets.first else {
            NSSound.beep()
            return
        }
        document.inOutRange = (clip.start, clip.end)
        if !loopEnabled {
            loopEnabled = true
            refreshToolbarControls()
        }
        viewStateDidChange()
        // Never `playback.loopRange` directly: `applyLoopRange` rewrites it
        // from `inOutRange`.
        applyLoopRange()
        setPlayhead(clip.start)
        playback.play()
    }

    private enum MotionSlot {
        case inEdge, out, during
    }

    /// The selected clips a motion applies to.
    private var motionTargets: [ClipSnapshot] {
        guard let document = document else { return [] }
        let snapshot = document.editedProject.snapshot
        return selectedClips.filter { InspectorTab.hasPixels($0, in: snapshot) }
    }

    private func setMotionCommand(slot: MotionSlot, sender: Any?) {
        let targets = motionTargets
        guard let document = document, let tag = (sender as? NSMenuItem)?.tag,
              !targets.isEmpty
        else {
            NSSound.beep()
            return
        // The one preset that ignores `period` entirely: a drift is a slow
        // push across the WHOLE clip, so its clock is the duration.
        DuringMotion::Drift => Term {
            f: 1.0 + 0.24 * amount * t / duration,
            ..Term::NONE
        },
    }
}

/// The two edge durations after the tent rule, in ticks as floats.
fn tent(motion: &Motion, duration: f64) -> (f64, f64) {
    let raw = |edge: &Option<MotionEdge>| edge.map_or(0.0, |e| e.duration as f64);
    let (mut arrive, mut leave) = (raw(&motion.r#in), raw(&motion.out));
    if arrive + leave > duration && arrive + leave > 0.0 {
        arrive = arrive * duration / (arrive + leave);
        leave = duration - arrive;
    }
    (arrive, leave)
}

/// A `during` slot that is actually running: `period` above zero, and a
/// duration to measure a drift against.
fn live_during(motion: &Motion, duration: f64) -> Option<(MotionDuring, f64, f64)> {
    let slot = motion.during?;
    let period = slot.period as f64;
    if period <= 0.0 || !period.is_finite() {
        return None;
    }
    // A drift divides by the clip's duration; every other kind ignores it.
    if matches!(slot.kind, DuringMotion::Drift) && duration <= 0.0 {
        return None;
